#include <iostream>
#include <unordered_map>
#include <string>
#include <chrono>
#include <mutex>
#include <vector>
#include <algorithm>
#include <cstdint>

using Clock = std::chrono::steady_clock;
using TimePoint = std::chrono::time_point<Clock>;

struct AttemptRecord {
    std::vector<TimePoint> timestamps;
    TimePoint lockout_until;
    bool is_locked;

    AttemptRecord() : is_locked(false), lockout_until(TimePoint::min()) {}
};

class RateLimiter {
private:
    std::unordered_map<std::string, AttemptRecord> records_;
    std::mutex mutex_;

    static constexpr int MAX_ATTEMPTS = 5;
    static constexpr int WINDOW_SECONDS = 60;
    static constexpr int LOCKOUT_SECONDS = 300;

    void prune_old_attempts(AttemptRecord& record, TimePoint now) {
        auto cutoff = now - std::chrono::seconds(WINDOW_SECONDS);
        record.timestamps.erase(
            std::remove_if(record.timestamps.begin(), record.timestamps.end(),
                [cutoff](const TimePoint& tp) { return tp < cutoff; }),
            record.timestamps.end());
    }

public:
    enum class Result { ALLOWED, RATE_LIMITED, LOCKED_OUT };

    Result check_and_record(const std::string& identifier) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto now = Clock::now();
        auto& record = records_[identifier];

        if (record.is_locked) {
            if (now < record.lockout_until) {
                return Result::LOCKED_OUT;
            }
            record.is_locked = false;
            record.timestamps.clear();
        }

        prune_old_attempts(record, now);
        record.timestamps.push_back(now);

        if (record.timestamps.size() > MAX_ATTEMPTS) {
            record.is_locked = true;
            record.lockout_until = now + std::chrono::seconds(LOCKOUT_SECONDS);
            return Result::LOCKED_OUT;
        }

        return Result::ALLOWED;
    }

    void reset(const std::string& identifier) {
        std::lock_guard<std::mutex> lock(mutex_);
        records_.erase(identifier);
    }
};

class AuthService {
private:
    RateLimiter limiter_;
    std::unordered_map<std::string, std::string> credentials_;

    std::string compute_composite_key(const std::string& username, const std::string& source_ip) {
        return username + ":" + source_ip;
    }

    bool verify_password(const std::string& username, const std::string& password) {
        auto it = credentials_.find(username);
        if (it == credentials_.end()) return false;
        return it->second == password; // simplified; real impl uses bcrypt
    }

public:
    AuthService() {
        credentials_["admin"] = "$2b$12$secrethash"; // placeholder for bcrypt hash
        credentials_["user1"] = "$2b$12$anotherhash";
    }

    struct AuthResult {
        bool success;
        std::string message;
        int remaining_attempts;
    };

    AuthResult authenticate(const std::string& username, const std::string& password,
                           const std::string& source_ip) {
        std::string rate_key = compute_composite_key(username, source_ip);

        auto limit_result = limiter_.check_and_record(rate_key);

        if (limit_result == RateLimiter::Result::LOCKED_OUT) {
            return {false, "Account temporarily locked. Try again later.", 0};
        }

        if (verify_password(username, password)) {
            limiter_.reset(rate_key);
            return {true, "Authentication successful.", 5};
        }

        return {false, "Invalid credentials.", -1};
    }

    AuthResult authenticate_with_retry(const std::string& username, const std::string& password,
                                       const std::string& source_ip, int max_retries = 3) {
        AuthResult result;
        for (int attempt = 0; attempt <= max_retries; ++attempt) {
            // All retries use the same rate-limiting key to prevent
            // bypass through retry mechanism
            result = authenticate(username, password, source_ip);

            if (result.success || result.remaining_attempts == 0) {
                break;
            }
        }
        return result;
    }
};

int main() {
    AuthService auth;

    // Normal authentication flow
    auto result = auth.authenticate("admin", "wrong_password", "192.168.1.1");
    std::cout << "Result: " << result.message << std::endl;

    // Retry-based authentication
    auto retry_result = auth.authenticate_with_retry("admin", "test", "10.0.0.1", 3);
    std::cout << "Retry result: " << retry_result.message << std::endl;

    return 0;
}
